class Solution {
public:
    string gcdOfStrings(string str1, string str2) {
        int n = str1.size(), m = str2.size();
        int g = gcd(n, m);
        for (int i = 0; i < n + m; i++) {
            char c1 = (i < n) ? str1[i] : str2[i - n];
            char c2 = (i < m) ? str2[i] : str1[i - m];
            if (c1 != c2) return "";
        }
        return str1.substr(0, g);
    }
private:
    int gcd(int a, int b) {
        while (b) {
            int t = b;
            b = a % b;
            a = t;
        }
        return a;
    }
};
